css:
/* Footer */
#colophon .site-footer-row-container-inner,#colophon .site-middle-footer-inner-wrap{background:transparent;}
#colophon{background-color:#08090b;background-image:url(https://rookiebusiness.de/wp-content/uploads/2026/11/rookie-business-footer-muster.png);background-size:260px 260px;border-top:1px solid rgba(255,255,255,.06);}
.rb-footer{padding:56px 0 8px;}
.rb-fgrid{display:grid;grid-template-columns:1.2fr 1fr 1fr 1.2fr 1fr;gap:32px;}
.rb-fbrand img{width:74px;height:auto;display:block;margin-bottom:16px;}
.rb-fbrand p{font-size:13px;line-height:1.6;color:var(--global-palette6,#8b93a1);margin:0;}
.rb-fcol h4{font-family:'Archivo Black',sans-serif;font-size:15px;letter-spacing:.06em;text-transform:uppercase;color:#fff;margin:0 0 18px;padding-bottom:8px;display:inline-block;border-bottom:2px solid var(--rb-teal,#00f0d4);}
.rb-fcol ul{list-style:none;margin:0;padding:0;}
.rb-fcol li{margin:0 0 9px;font-size:13px;line-height:1.4;}
.rb-fcol a{color:var(--global-palette5,#c5cad3);text-decoration:none;font-weight:600;transition:color .15s;}
.rb-fcol a:hover{color:var(--rb-teal,#00f0d4);}
.rb-fbar{display:flex;justify-content:space-between;align-items:center;gap:16px;flex-wrap:wrap;margin-top:40px;padding-top:22px;border-top:1px solid rgba(255,255,255,.08);}
.rb-fship,.rb-fpay{display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.rb-fchip{font-size:12px;font-weight:600;color:var(--global-palette5,#c5cad3);border:1px solid rgba(255,255,255,.14);border-radius:999px;padding:6px 12px;}
.rb-flabel{font-size:12px;color:var(--global-palette6,#8b93a1);margin-right:4px;}
.rb-pp{background:#fff;border-radius:6px;padding:6px 12px;font-size:14px;line-height:1;font-style:italic;color:#003087;white-space:nowrap;}
.rb-pp b{font-weight:800;color:#003087;}.rb-pp i{font-weight:800;color:#009cde;}
.rb-pp-later{font-style:normal;font-size:12px;font-weight:700;color:#003087;}
.rb-pp-later b,.rb-pp-later i{font-style:italic;font-size:14px;}
#colophon .site-bottom-footer-wrap{border-top:0;}
#colophon .site-bottom-footer-wrap .footer-html{font-size:12px;color:var(--global-palette6,#8b93a1);}
@media (max-width:1024px){.rb-fgrid{grid-template-columns:repeat(3,1fr);}.rb-fbrand{grid-column:1 / -1;}}
@media (max-width:600px){.rb-fgrid{grid-template-columns:1fr 1fr;gap:28px 20px;}.rb-fbar{justify-content:center;}}
